spec.expr:
max_over_time((
  max by (instance) (
      (
        prometheus_remote_storage_highest_timestamp_in_seconds{job=~"integrations/(self|alloy)", instance=~"$agent"}
        - ignoring(url, remote_name) group_right()
        prometheus_remote_storage_queue_highest_sent_timestamp_seconds{job=~"integrations/(self|alloy)", instance=~"$agent"}
      ) < 31536000
    )
)[$__range:1m])

sum_over_time(
  (
    max by (instance) (
      (
        prometheus_remote_storage_highest_timestamp_in_seconds{job=~"integrations/(self|alloy)", instance=~"$agent"}
        - ignoring(url, remote_name) group_right()
        prometheus_remote_storage_queue_highest_sent_timestamp_seconds{job=~"integrations/(self|alloy)", instance=~"$agent"}
      ) < 31536000
    )
    > bool 120
  )[$__range:1m]
) * 60

label_replace(
  label_join(
    label_replace(
      label_join(
        label_replace(
          label_replace(
            max_over_time(scrape_duration_seconds{job=~"$job"}[$__interval]),
            "instance", "$1", "instance", "https?://(.*)"
          ),
          "instance", "$1$2", "instance", "([^.:/]*[a-zA-Z][^.:/]*)\\.[^:/]+(.*)"
        ),
        "instance", " ", "instance", "database"
      ),
      "lport", "$1", "instance", "(?:127\\.0\\.0\\.1|localhost):([0-9]+) ?"
    ),
    "hostport", ":", "host", "lport"
  ),
  "instance", "$1", "hostport", "(.+:[0-9]+)"
)

label_replace(
  label_join(
    label_replace(
      label_join(
        label_replace(
          label_replace(
            last_over_time(scrape_samples_post_metric_relabeling{job=~"$job"}[30m]),
            "instance", "$1", "instance", "https?://(.*)"
          ),
          "instance", "$1$2", "instance", "([^.:/]*[a-zA-Z][^.:/]*)\\.[^:/]+(.*)"
        ),
        "instance", " ", "instance", "database"
      ),
      "lport", "$1", "instance", "(?:127\\.0\\.0\\.1|localhost):([0-9]+) ?"
    ),
    "hostport", ":", "host", "lport"
  ),
  "instance", "$1", "hostport", "(.+:[0-9]+)"
)

